    #[allow(unused_variables)]
    fn create_dir(&self, target: &CreationTarget, is_parent: bool) -> UResult<bool> {
        if target.exists() && !self.recursive {
            return Err(USimpleError::new(
                1,
                format!("{}: File exists", target.as_path().display()),
            ));
        }
        if target.is_empty() {
            return Ok(false);
        }

        if self.recursive {
            match target.parent() {
                Some(p) => self.create_dir(&CreationTarget::from_path(p), true)?,
                None => {
                    USimpleError::new(1, "failed to create whole tree");
                }
            }
        }
        match std::fs::create_dir(target.as_path()) {
            Ok(()) => {
                if self.verbose {
                    let notice = CreatedPathNotice::for_directory(
                        uucore::util_name(),
                        target.as_path(),
                    );
                    println!(
                        "{}: created directory {}",
