                    // which is umask modified by 'u+wx'
                    let spec = mode::DirectoryPermissionSpec::for_parents();
                    chmod(
                        target.as_path(),
                        (!spec.umask() & spec.permission_mask()) | spec.owner_write_search(),
                    )?;
                }
                Ok(true)
            }
            Err(_) if target.is_dir() => Ok(false),
            Err(e) => Err(e.into()),
        }
    }
}

